    [
        'id'=>'cse-verbal-reading-grammar-and-cohesion','board'=>'civil-service','subject'=>'verbal-ability','title'=>'Civil Service Verbal Ability: Reading, Grammar, and Cohesion','pdf'=>'cse-verbal-reading-grammar-and-cohesion.pdf',
        'scope'=>['csc-cse-ppt-scope-2026'],'instruction'=>['purdue-owl-grammar','openstax-reading-writing','deped-filipino-curriculum-guide','kwf-balarila-pambansa','kwf-diksiyonaryo'],
        'scope_note'=>'CSC verbal scope includes vocabulary, grammar and correct usage, paragraph organization, and reading comprehension in English and Filipino. This lesson uses original examples in both languages; it does not assume that English grammar can be transferred mechanically to Filipino.',
        'objectives'=>['Find a passage’s central claim and distinguish it from supporting detail.','Use context to infer word meaning and evaluate a conclusion.','Apply clear sentence and paragraph relationships in English and Filipino.'],
        'sections'=>[
            ['id'=>'main-idea-evidence-and-inference','heading'=>'1. Central idea, evidence, and careful inference','body'=>'Read the question first to know whether it asks for a stated detail, central idea, inference, purpose, or evaluation. A central idea explains what the passage as a whole is doing; a detail supports one part. For inference, combine the text with the smallest necessary assumption and reject options that add facts the author never supplies. A change observed after an action does not by itself prove the action caused it. In Filipino, distinguish the pangunahing diwa from pantulong na detalye and make a hinuha that stays within the tekstong binasa.','concepts'=>['cse-reading-comprehension','cse-paragraph-organization','critical-reading-evidence-quality','english-inference-evidence','filipino-pagbasa-pangunahing-diwan']],
            ['id'=>'vocabulary-and-word-choice','heading'=>'2. Vocabulary from context','body'=>'When a word is unfamiliar, reread the sentence and its neighboring sentences. Look for a definition, contrast, example, cause, or repeated idea that narrows the meaning. Substitute a candidate meaning and check whether the sentence still makes sense without changing the author’s claim. In Filipino, inspect affixes and the word’s role in the sentence, then consult a reliable Filipino dictionary when context remains ambiguous. A plausible dictionary meaning may still be wrong for this sentence if it does not fit the surrounding argument.','concepts'=>['cse-word-meaning','cse-contextual-inference','cse-filipino-word-usage']],
            ['id'=>'grammar-and-sentence-revision','heading'=>'3. Grammar as a meaning check','body'=>'For English subject–verb agreement, locate the grammatical subject rather than the nearest noun; intervening phrases do not change the subject’s number. A pronoun should have a clear antecedent and agree in number and reference. Parallel items should use matching grammatical forms. In Filipino, identify the panaguri and simuno in the actual sentence and use the appropriate pang-ugnay and word form; do not impose English agreement patterns where Filipino grammar works differently. Revision should make the intended relationship clearer, not merely sound more formal.','concepts'=>['cse-error-recognition','cse-sentence-structure','cse-grammar-application','cse-pronoun-reference','cse-parallel-structure','filipino-gramatika-wastong-gamit']],
            ['id'=>'paragraph-order-and-cohesion','heading'=>'4. Paragraph order and cohesion','body'=>'A coherent paragraph gives each sentence a job: introduce the point, explain it, support it, or connect it to the next idea. Track reference words, time markers, contrast, and cause-and-effect signals. A sentence that begins with “however” needs a genuine contrast; a pronoun should point to a clear noun; a concluding sentence should follow from the evidence already given. Test a paragraph order by reading the transitions aloud and checking whether the logic remains clear without adding an unstated premise.','concepts'=>['cse-paragraph-organization','cse-paragraph-cohesion']],
        ],
        'examples'=>[['heading'=>'Avoid a causal overclaim','prompt'=>'A report says processing time fell after a checklist was introduced, but no comparison group was used. What is the strongest conclusion?','steps'=>['State only the observed sequence: the decrease followed introduction of the checklist.','Check whether another group or design isolates the checklist’s effect.','Avoid claiming causation when other changes remain possible.'],'answer'=>'The result is promising, but causation is not established.','check'=>'This conclusion matches the stated evidence and does not add a cause.']],
        'misconceptions'=>['The longest option is always the central idea.','A temporal “after” relationship proves causation.','English grammatical categories apply identically in Filipino.'],
        'patterns'=>['Label the task before reading options.','Quote or paraphrase the exact evidence supporting an inference.','Check grammar against intended meaning in the language used.'],
        'questions'=>[['id'=>'600','section'=>'main-idea-evidence-and-inference','concept'=>'cse-reading-comprehension','sources'=>['csc-cse-ppt-scope-2026','openstax-reading-writing']]],
    ],
    [
        'id'=>'cpa-advanced-accounting-ownership-and-consolidation','board'=>'cpa','subject'=>'cpa-advanced-accounting','title'=>'Advanced Accounting: Ownership, Profit Allocation, and Consolidation','pdf'=>'cpa-advanced-accounting-ownership-and-consolidation.pdf',
        'scope'=>['prc-accountancy-board-page'],'instruction'=>['ifrs-conceptual-framework','ifrs-ifrs-3-business-combinations','ifrs-ifrs-10-consolidated-financial-statements','openstax-principles-managerial-accounting'],
        'scope_note'=>'PRC has issued revised 2026 Tables of Specifications for the six LECPA subjects. This original lesson focuses on selected partnership-allocation and consolidation reasoning. Apply the current Philippine-adopted standards and the specific facts of a case; this short guide is not a complete advanced-accounting reviewer.',
        'objectives'=>['Allocate a partnership result using the agreement’s stated priority and residual ratio.','Explain why consolidated statements treat a parent and controlled subsidiaries as one economic reporting group.','Identify intercompany items that must be examined before interpreting consolidated totals.'],
        'sections'=>[
            ['id'=>'partnership-agreements-and-allocations','heading'=>'1. Partnership agreements and profit allocation','body'=>'A partnership allocation problem is an ordered calculation, not an automatic equal split. Read the agreement for salaries, interest on capital, preferred amounts, and the residual-sharing ratio; then determine whether the stated allowances are distributions of profit or expenses in a particular accounting context. Compute the total allowances first, compare them with available profit, and allocate the remaining amount using the stated ratio. If allowances exceed the available profit, do not force a positive residual; follow the agreement’s loss or deficit rule. State every assumption so a reviewer can reproduce the allocation.','concepts'=>['cpa-advanced-accounting-partnerships-core','cpa-advanced-accounting-profit-allocation-core','cpa-advanced-accounting-agreement-core','cpa-advanced-accounting-measurement-core']],
            ['id'=>'business-combinations-and-control','heading'=>'2. Business combinations and control','body'=>'A business-combination analysis first identifies the acquirer and acquisition date, then considers the identifiable assets and liabilities and the consideration under the applicable standard. Consolidated reporting depends on control rather than the mere existence of an investment or a common brand. The investor assesses power over relevant activities, exposure or rights to variable returns, and the ability to use power to affect those returns under IFRS 10’s control model. Apply the standards adopted in the Philippines for the reporting period, and distinguish an acquisition calculation from later-period consolidation.','concepts'=>['cpa-advanced-accounting-combinations-core','cpa-advanced-accounting-consolidation-core','cpa-advanced-accounting-nci-core']],
            ['id'=>'intercompany-elimination-and-translation','heading'=>'3. Intercompany eliminations and foreign operations','body'=>'Consolidated statements combine like items of the parent and subsidiaries, then remove intragroup balances and transactions so the group does not report activity with itself as an external result. Identify the originating entities, transaction direction, reporting date, and whether profit remains in group assets. Foreign-operation translation adds another layer: distinguish the entity’s functional currency from the presentation currency and apply the relevant standard to assets, liabilities, income, and translation differences. These are not interchangeable topics; use the applicable IFRS requirements and source records for the specific case.','concepts'=>['cpa-advanced-accounting-intercompany-core','cpa-advanced-accounting-elimination-core','cpa-advanced-accounting-intercompany-balances-core','cpa-advanced-accounting-foreign-currency-core','cpa-advanced-accounting-translation-core']],
            ['id'=>'other-advanced-accounting-pathways','heading'=>'4. Other advanced-accounting pathways','body'=>'Branch accounting, joint arrangements, liquidation, withdrawal, dividends, and asset transfers each require a transaction model that fits the legal arrangement and accounting policy. Begin with the parties, their rights and obligations, the reporting entity, and the event being measured. Keep a schedule that reconciles opening balances, current activity, allocations, eliminations, and ending balances. This broad introduction does not teach the recognition details of every pathway; consult the current LECPA TOS and applicable Philippine-adopted standards before treating a topic as covered.','concepts'=>['cpa-advanced-accounting-branch-core','cpa-advanced-accounting-joint-arrangements-core','cpa-advanced-accounting-liquidation-core','cpa-advanced-accounting-withdrawal-core','cpa-advanced-accounting-dividends-core','cpa-advanced-accounting-fixed-assets-core','cpa-advanced-accounting-branch-inventory-core','cpa-advanced-accounting-profit-attribution-core']],
        ],
        'examples'=>[['heading'=>'Allocate partnership profit','prompt'=>'A partnership earns ₱360,000. A receives a ₱120,000 salary allowance and B ₱80,000; capital interest is 10% on ₱400,000 and ₱200,000, respectively; the residual is shared 3:2. Find A’s total allocation.','steps'=>['Salary allowances total ₱200,000; capital-interest allowances are ₱40,000 and ₱20,000, so total allowances are ₱260,000.','Residual profit is ₱360,000 − ₱260,000 = ₱100,000.','A receives 3/5 of the residual, or ₱60,000; add A’s salary ₱120,000 and interest ₱40,000.'],'answer'=>'A’s total allocation is ₱220,000.','check'=>'The partners receive ₱360,000 in total: ₱220,000 for A and ₱140,000 for B.']],
        'misconceptions'=>['Salary or interest allowances are always operating expenses.','An investment automatically gives its holder control.','Consolidation means adding every ledger balance without eliminations.'],
        'patterns'=>['Read the agreement before calculating allocations.','Separate acquisition-date analysis from later reporting.','Reconcile intercompany balances before interpreting group results.'],
        'questions'=>[['id'=>'1279','section'=>'partnership-agreements-and-allocations','concept'=>'cpa-advanced-accounting-partnerships-core','sources'=>['prc-accountancy-board-page','ifrs-conceptual-framework']]],
    ],
    [
        'id'=>'cpa-financial-accounting-recognition-measurement-and-reporting','board'=>'cpa','subject'=>'cpa-financial-accounting','title'=>'Financial Accounting: Recognition, Measurement, and Reporting Checks','pdf'=>'cpa-financial-accounting-recognition-measurement-and-reporting.pdf',
        'scope'=>['prc-accountancy-board-page'],'instruction'=>['ifrs-conceptual-framework','ifrs-ias-2-inventories','ifrs-ias-16-property-plant-equipment','ifrs-ifrs-15-revenue','ifrs-ias-37-provisions','ifrs-ias-36-impairment','ifrs-ias-7-cash-flow-statements','ifrs-ifrs-16-leases'],
        'scope_note'=>'The current PRC LECPA TOS is the official scope reference. This lesson organizes selected accrual, measurement, presentation, and analysis methods; use the Philippine-adopted version and effective date of each standard for a reporting period. It does not replace the standards text.',
        'objectives'=>['Apply accrual timing to expenses and unearned/earned customer amounts.','Distinguish recognition from measurement and presentation.','Use reconciliation checks when interpreting financial-statement effects.'],
        'sections'=>[
            ['id'=>'accruals-cutoff-and-deferrals','heading'=>'1. Accruals, cut-off, and customer advances','body'=>'Accrual accounting records the economic event in the period it occurs, subject to the applicable recognition requirements, rather than simply following cash movement. An incurred but unpaid utility expense belongs to the period of use; an expired portion of prepaid insurance is an expense; a customer advance remains a liability until the relevant performance or earning conditions are met. At period end, identify the service or right received, the time interval, supporting documents, and whether an amount is earned, incurred, paid, or still deferred. Cut-off errors often arise when these states are treated as synonyms.','concepts'=>['cpa-financial-accounting-accruals-core','cpa-financial-accounting-transactions-core','cpa-financial-accounting-liabilities-core']],
            ['id'=>'asset-and-revenue-measurement','heading'=>'2. Assets, inventory, revenue, and measurement','body'=>'Recognition asks whether an item belongs in the statements under the applicable standard; measurement asks which amount and subsequent measurement basis apply. Inventory, property and equipment, revenue, leases, and financial instruments each have their own criteria and measurement mechanics. Do not generalize one standard’s model across every asset or contract. Trace the transaction from contract or purchase evidence to the account, estimate, and note disclosure; verify the current adopted text and effective date. A carrying amount is not automatically recoverable simply because it was recorded at cost, and revenue timing follows the relevant performance obligations rather than cash collection alone.','concepts'=>['cpa-financial-accounting-inventory-core','cpa-financial-accounting-ppe-core','cpa-financial-accounting-revenue-core','cpa-financial-accounting-leases-core','cpa-financial-accounting-allowance-core']],
            ['id'=>'estimates-impairment-and-cash-flows','heading'=>'3. Estimates, impairment, and cash-flow interpretation','body'=>'Estimates use available evidence at a measurement date and may need revision when conditions or information change. A provision requires the criteria in the applicable standard; uncertainty alone does not justify recording any desired reserve. An impairment assessment compares carrying amounts with the measure required by the relevant standard and unit of account. Cash-flow analysis then reconciles opening and closing cash through operating, investing, and financing activity, while keeping noncash transactions separate. Tie reported changes back to ledgers, disclosures, and prior-period comparatives before drawing a conclusion about performance or liquidity.','concepts'=>['cpa-financial-accounting-provisions-core','cpa-financial-accounting-estimates-core','cpa-financial-accounting-impairment-core','cpa-financial-accounting-cash-flow-core','cpa-financial-accounting-analysis-core','cpa-financial-accounting-interpretation-core']],
            ['id'=>'presentation-and-review-trail','heading'=>'4. Presentation and a reviewable audit trail','body'=>'Financial statements tell a connected story: assets and liabilities at a date, income and expenses over a period, and cash movements across that period. Classification and presentation should follow the standard and reporting context rather than a convenient ratio. Maintain a trail from source document to journal entry, calculation schedule, general ledger, statement line, and disclosure. When two sources disagree, resolve the underlying fact and document the judgment; do not force the ledger to match an unsupported expectation.','concepts'=>['cpa-financial-accounting-presentation-core','cpa-financial-accounting-equity-core','cpa-financial-accounting-classification-core']],
        ],
        'examples'=>[['heading'=>'Separate expenses from earned revenue','prompt'=>'At reporting date, utilities incurred are ₱18,000, insurance expired is ₱7,000, and a ₱12,000 customer deposit has been earned. What expense is recognized from the first two items?','steps'=>['Identify utilities as incurred expense: ₱18,000.','Identify expired insurance as the used portion: ₱7,000.','Add only the expense amounts; the customer deposit affects revenue, not this expense total.'],'answer'=>'Recognized expense is ₱25,000.','check'=>'Cash payment timing does not change the stated incurrence or expiry facts.']],
        'misconceptions'=>['Cash received always means revenue has been earned.','An estimate is an arbitrary reserve rather than a supportable measurement.','A financial-statement total can be checked without its source and period.'],
        'patterns'=>['Name the reporting period and economic event.','Keep recognition, measurement, and presentation as separate questions.','Trace the number from evidence through ledger to disclosure.'],
        'questions'=>[['id'=>'1259','section'=>'accruals-cutoff-and-deferrals','concept'=>'cpa-financial-accounting-accruals-core','sources'=>['prc-accountancy-board-page','ifrs-conceptual-framework']]],
    ],
    [
        'id'=>'cpa-management-services-cvp-and-decisions','board'=>'cpa','subject'=>'cpa-management-services','title'=>'Management Services: Contribution, Break-Even, and Decision Models','pdf'=>'cpa-management-services-cvp-and-decisions.pdf',
        'scope'=>['prc-accountancy-board-page'],'instruction'=>['openstax-principles-managerial-accounting','openstax-introductory-statistics-2e'],
        'scope_note'=>'PRC’s 2026 revised LECPA TOS governs official subject coverage. This lesson teaches selected internal planning tools using stated assumptions; its hypothetical figures do not represent Philippine tax, financial-reporting, or business advice.',
        'objectives'=>['Compute unit contribution and break-even volume.','Explain the assumptions and relevant range behind a CVP result.','Compare a decision using relevant costs and state nonfinancial constraints.'],
        'sections'=>[
            ['id'=>'contribution-and-break-even','heading'=>'1. Contribution margin and break-even','body'=>'For one product under a linear cost-volume-profit model, unit contribution margin equals selling price per unit less variable cost per unit. Fixed cost divided by unit contribution gives break-even units; fixed cost divided by contribution-margin ratio gives break-even sales dollars. At break-even, total contribution exactly covers fixed cost and operating income is zero. Keep units and currency consistent, and distinguish the contribution from gross margin or cash flow. For a multi-product setting, a weighted mix assumption matters because products may have different contribution margins.','concepts'=>['cpa-management-services-cvp-core','cpa-management-services-sales-mix-core']],
            ['id'=>'cvp-assumptions-and-sensitivity','heading'=>'2. Test assumptions and sensitivity','body'=>'CVP results are conditional estimates. Common simplifying assumptions include a stable selling price, linear variable cost, fixed cost within a relevant range, and known sales mix. A change in capacity, overtime, discounting, product mix, or inventory can break those assumptions. Sensitivity analysis changes one or more inputs transparently and recomputes contribution and break-even; it does not guarantee the forecast. A margin-of-safety measure compares expected or actual sales with break-even, and operating leverage describes how a change in sales can affect operating income under the modeled cost structure.','concepts'=>['cpa-management-services-cvp-core','cpa-management-services-constraints-core','cpa-management-services-performance-core']],
            ['id'=>'relevant-costs-and-budget-variance','heading'=>'3. Relevant costs, budgets, and variance questions','body'=>'A decision-relevant cost differs between alternatives and relates to a future consequence. A sunk cost is already incurred and cannot be changed by the current choice, while an avoidable future cost may matter. Compare alternatives on consistent units and horizon, then include capacity, quality, delivery, safety, and strategic constraints that the arithmetic omits. Budget variances are signals to investigate: define the benchmark, actual measure, flexible volume basis, and cause before calling a variance favorable or unfavorable. Responsibility accounting should focus on items a manager can reasonably influence.','concepts'=>['cpa-management-services-relevant-costing-core','cpa-management-services-budgeting-core','cpa-management-services-variance-core','cpa-management-services-sunk-cost-core','cpa-management-services-standard-costing-core']],
        ],
        'examples'=>[['heading'=>'Find break-even volume','prompt'=>'A product sells for ₱80, has variable cost ₱50, and fixed cost ₱240,000. Find break-even volume under the one-product linear model.','steps'=>['Unit contribution = ₱80 − ₱50 = ₱30 per unit.','Break-even units = fixed cost ÷ unit contribution = ₱240,000 ÷ ₱30.','Check revenue and total cost at that volume.'],'answer'=>'8,000 units.','check'=>'Sales are ₱640,000; variable costs are ₱400,000; contribution of ₱240,000 covers fixed cost exactly.']],
        'misconceptions'=>['Break-even is reliable outside the stated relevant range.','Fixed cost per unit remains fixed as volume changes.','A favorable variance automatically reflects good management.'],
        'patterns'=>['Write the assumptions before calculating break-even.','Label contribution per unit and total contribution separately.','Investigate the cause and controllability of a variance.'],
        'questions'=>[['id'=>'1299','section'=>'contribution-and-break-even','concept'=>'cpa-management-services-cvp-core','sources'=>['prc-accountancy-board-page','openstax-principles-managerial-accounting']]],
    ],
    [
        'id'=>'cpa-regulatory-framework-law-ethics-and-evidence','board'=>'cpa','subject'=>'cpa-regulatory-framework','title'=>'CPA Regulatory Framework: Authority, Ethics, Contracts, and Audit Evidence','pdf'=>'cpa-regulatory-framework-law-ethics-and-evidence.pdf',
        'scope'=>['prc-accountancy-board-page'],'instruction'=>['philippines-accountancy-act','philippine-cpa-code-of-ethics','philippines-civil-code-business-law','philippines-revised-corporation-code','prc-accountancy-auditing-standards-2026'],
        'scope_note'=>'The PRC Board of Accountancy publishes current LECPA TOS and Philippine professional issuances. This introductory lesson teaches source-checking and selected legal/audit reasoning; law and standards change, and the current primary text and effective date govern an actual professional decision.',
        'objectives'=>['Identify which primary authority and date control a regulatory question.','Analyze a basic contract sequence from the facts given without inventing missing terms.','Explain why audit evidence must address the relevant assertion and risk.'],
        'sections'=>[
            ['id'=>'authority-professional-regulation-and-ethics','heading'=>'1. Professional authority and ethical duties','body'=>'Start a regulatory question by naming the profession, the act or decision, the authority responsible, and the date relevant to the case. Republic Act No. 9298 establishes the Philippine accountancy regulatory framework; PRC and Board of Accountancy resolutions, applicable laws, and professional pronouncements provide additional requirements within their scope. Ethical analysis identifies the fundamental principle at risk, the relevant relationship or pressure, and safeguards required by the applicable Philippine Code of Ethics. A general ethical value is not a substitute for the actual rule, independence requirement, or effective date.','concepts'=>['cpa-regulatory-framework-professional-law-core','cpa-regulatory-framework-conflict-core','cpa-regulatory-framework-confidentiality-core']],
            ['id'=>'contract-formation-and-fact-sequence','heading'=>'2. Contract questions: order the facts, then check the rule','body'=>'For a contract problem, write the dated sequence of offer, acceptance, communication, revocation, and any stated condition. Then consult the relevant Civil Code provisions and determine which act was legally effective and when. Do not assume a time limit, delivery method, or jurisdiction-specific deadline unless the problem or source supplies it. The distinction between dispatch and receipt can matter for communications. If an essential fact is missing, state the conditional conclusion rather than filling the gap with an unstated rule. This method makes an answer traceable and protects against overconfident legal generalization.','concepts'=>['cpa-regulatory-framework-contracts-core','cpa-regulatory-framework-obligations-core','cpa-regulatory-framework-validity-core','cpa-regulatory-framework-formalities-core']],
            ['id'=>'corporations-and-entity-records','heading'=>'3. Corporate authority and entity evidence','body'=>'Corporate analysis begins by identifying the entity, its governing documents, the decision-maker, and the act at issue. The Revised Corporation Code distinguishes corporate forms and assigns requirements for organizational and governance acts; special laws may also apply. For an accounting or audit task, connect a recorded transaction to minutes, contracts, ownership records, bank evidence, or other relevant documentation. A corporate record is evidence to evaluate, not proof by title alone. Check amendments and current SEC rules before advising on a live corporate act.','concepts'=>['cpa-regulatory-framework-corporate-law-core','cpa-regulatory-framework-governance-core','cpa-regulatory-framework-records-core']],
            ['id'=>'audit-standards-and-evidence','heading'=>'4. Audit standards and assertion-directed evidence','body'=>'Audit procedures should respond to assessed risk and the assertion being tested, such as existence, completeness, valuation, rights and obligations, or presentation. Evidence quality depends on relevance and reliability in context; one document may support one assertion while leaving another untested. Read the applicable Philippine Auditing Standard, including its effective date and adoption source, before treating a procedure as required. A sample reconciliation or analytical procedure is a learning example, not a complete audit program or assurance conclusion.','concepts'=>['cpa-regulatory-framework-records-core','cpa-regulatory-framework-disclosure-core','cpa-regulatory-framework-interpretation-core']],
        ],
        'examples'=>[['heading'=>'Order offer, revocation, and acceptance','prompt'=>'An offer is communicated January 10, revocation January 12, and acceptance January 13. What conclusion follows from the stated sequence for this exercise?','steps'=>['Write the sequence in order: offer, revocation, acceptance.','The stated revocation precedes the stated acceptance.','Do not add an unstated deadline or communication rule; consult the applicable Civil Code provisions for a real case.'],'answer'=>'Under the facts and assumptions supplied in the exercise, no contract formed because revocation preceded acceptance.','check'=>'The reasoning depends on the exercise’s facts and does not decide questions of notice or effective receipt that were not supplied.']],
        'misconceptions'=>['A PRC webpage title proves every later amendment is in force.','A legal conclusion can ignore when a communication became effective.','A document is persuasive evidence for every audit assertion.'],
        'patterns'=>['Record the authority, section, version, and effective date.','Sequence legal events before applying a rule.','Tie each audit procedure to a stated risk and assertion.'],
        'questions'=>[['id'=>'1339','section'=>'contract-formation-and-fact-sequence','concept'=>'cpa-regulatory-framework-contracts-core','sources'=>['prc-accountancy-board-page','philippines-civil-code-business-law']]],
    ],
    [
        'id'=>'cpa-taxation-computation-and-current-law-workflow','board'=>'cpa','subject'=>'cpa-taxation','title'=>'Taxation: Computation Workflow and Current-Law Verification','pdf'=>'cpa-taxation-computation-and-current-law-workflow.pdf',
        'scope'=>['prc-accountancy-board-page'],'instruction'=>['philippines-national-internal-revenue-code','bir-tax-issuances-reference','philippines-ease-of-paying-taxes-act','bir-digital-services-vat-guidance'],
        'scope_note'=>'The PRC 2026 LECPA TOS is the exam-scope source. Philippine tax rules, rates, filing duties, and BIR issuances are time-sensitive. This lesson teaches a calculation workflow and uses only rates or treatments explicitly supplied in a hypothetical problem; it does not state a current tax rate or provide tax advice.',
        'objectives'=>['Separate facts, tax base, treatment, rate, and liability in a tax problem.','Compute a base from a supplied schedule without importing an unstated rate.','Verify a current requirement in the applicable law and BIR issuance.'],
        'sections'=>[
            ['id'=>'tax-source-and-taxpayer-facts','heading'=>'1. Begin with the taxpayer, transaction, and source date','body'=>'Before calculating, identify the taxpayer, tax type, transaction date, place, accounting period, and facts that affect classification. Then locate the controlling provision in the National Internal Revenue Code as amended and the applicable BIR regulation, revenue memorandum, or other issuance. Check publication, effectivity, amendments, transition rules, and whether the source covers this taxpayer and transaction. A summary page or old reviewer can help you find a provision but cannot establish a current rate or deadline. Preserve the source and date behind each assumption in the computation.','concepts'=>['cpa-taxation-tax-basics-core','cpa-taxation-current-law-core','cpa-taxation-administration-core']],
            ['id'=>'tax-base-and-supplied-schedule','heading'=>'2. Build a tax base from stated components','body'=>'A tax-base calculation begins with the gross amount identified by the problem, then applies only inclusions, exclusions, deductions, credits, or adjustments that are supported by the stated facts and governing rule. Keep separate columns for the source amount, treatment, rule citation, and arithmetic. A permitted cost may reduce a base only if it qualifies under the applicable rules and evidence; the word “cost” by itself does not prove deductibility. When an examination item supplies a tax schedule, use the supplied treatment for that exercise and label the result as conditional on that schedule.','concepts'=>['cpa-taxation-tax-basics-core','cpa-taxation-tax-base-core','cpa-taxation-deductions-core','cpa-taxation-substantiation-core']],
            ['id'=>'indirect-tax-and-compliance-checks','heading'=>'3. Indirect taxes, documentation, and compliance','body'=>'Indirect-tax problems may turn on transaction type, place of supply, registration, exemptions, timing, documentation, and the rule effective on the transaction date. Separate output tax, input tax, tax-inclusive amounts, and cash remittance rather than combining them prematurely. BIR issuances can implement statutory changes and contain transition details, so confirm the exact issuance and its status. For filing and payment, verify the current form, channel, due date, and taxpayer category with an official BIR source. A worked classroom amount does not establish a real person’s filing obligation.','concepts'=>['cpa-taxation-vat-core','cpa-taxation-filing-core','cpa-taxation-withholding-core','cpa-taxation-compliance-core']],
            ['id'=>'review-and-reconcile-a-tax-computation','heading'=>'4. Review and reconcile the computation','body'=>'A reviewable computation exposes its assumptions, units, tax period, rate source, rounding rule, and supporting records. Recalculate the base independently, reconcile it to books or source documents, and test whether each adjustment is included once. Separate a book-to-tax adjustment from a cash payment and from a return line. If a required rule or fact is missing, identify that gap rather than filling it from memory. For a live transaction, the responsible professional must verify current law and case facts before relying on a study example.','concepts'=>['cpa-taxation-reconciliation-core','cpa-taxation-records-core','cpa-taxation-ethics-core']],
        ],
        'examples'=>[['heading'=>'Compute a base using a supplied schedule','prompt'=>'A hypothetical exercise states receipts of ₱500,000 and allowable costs of ₱180,000 under its supplied schedule. What base remains before any further adjustments?','steps'=>['Use only the treatment supplied for the exercise.','Subtract the stated allowable costs: ₱500,000 − ₱180,000.','Label the result as the exercise base before other adjustments.'],'answer'=>'₱320,000 under the supplied hypothetical schedule.','check'=>'This arithmetic does not establish that those costs are deductible under current Philippine tax law.']],
        'misconceptions'=>['A historical reviewer’s rate remains current by default.','Every recorded business cost is automatically deductible.','A taxable base is the same as the final tax liability.'],
        'patterns'=>['Identify tax type, person, transaction date, and period.','Cite the exact source for every treatment and rate.','Reconcile adjustments and disclose missing facts.'],
        'questions'=>[['id'=>'1359','section'=>'tax-base-and-supplied-schedule','concept'=>'cpa-taxation-tax-basics-core','sources'=>['prc-accountancy-board-page','philippines-national-internal-revenue-code']]],
    ],
    [
        'id'=>'let-english-reading-language-and-composition','board'=>'let','subject'=>'english','title'=>'LET English: Reading Evidence, Grammar, and Composition','pdf'=>'let-english-reading-language-and-composition.pdf',
        'scope'=>['prc-let-enhanced-tos-2025','prc-lept-alignment-guidance-2025'],'instruction'=>['deped-k12-english-curriculum-guide','openstax-reading-writing','purdue-owl-grammar'],
        'scope_note'=>'Use PRC’s current LEPT TOS and alignment issuances for exam scope. DepEd’s K–12 English guide supports the curriculum competencies represented here. This original lesson covers selected language and reading skills; it is not a complete English specialization guide.',
        'objectives'=>['Infer a conclusion from a short passage while respecting its evidence limits.','Explain how grammar and reference choices affect meaning.','Organize a short response around a clear claim and supporting evidence.'],
        'sections'=>[
            ['id'=>'reading-claim-and-evidence','heading'=>'1. Read a claim through its evidence','body'=>'A reader should distinguish what a passage states, what it suggests, and what remains unknown. Identify the central claim, the evidence offered, and the connection between them. Then ask whether the evidence actually supports the conclusion or merely occurs at the same time. In teaching and assessment, a response that cites relevant details and explains their connection is stronger than one that repeats a claim without evidence. Use an original passage as a shared text, then ask learners to justify one inference and identify an alternative explanation.','concepts'=>['critical-reading-evidence-quality','english-inference-evidence','inference-evidence-based-conclusions','main-idea-and-support-central-idea','main-idea-and-support-supporting-evidence']],
            ['id'=>'sentence-grammar-and-reference','heading'=>'2. Grammar, agreement, and clear reference','body'=>'When revising a sentence, locate its main subject and verb, then check whether their forms agree. A phrase between subject and verb may be informative but does not normally become the subject. Pronouns need an identifiable antecedent and a clear number reference; modifiers should sit close to what they describe. A grammatical correction should preserve the intended proposition. Read the revised sentence in context to make sure a local edit has not changed the writer’s meaning or obscured the relationship between ideas.','concepts'=>['subject-verb-agreement-compound-subjects','pronouns-pronoun-reference','pronouns-pronoun-antecedent-agreement','modifiers-misplaced-modifiers','parallelism-parallel-items','verb-tenses-tense-consistency']],
            ['id'=>'context-and-text-structure','heading'=>'3. Vocabulary, purpose, and text structure','body'=>'Use context clues as evidence rather than as a guess: nearby definitions, examples, contrasts, and cause-and-effect relationships narrow a word’s meaning. Text structure can signal whether a writer is comparing ideas, explaining a sequence, or describing a problem and response. Purpose and tone should be inferred from the whole passage, including word choice and the intended audience. A single loaded word is not enough to label the tone if the rest of the passage points elsewhere.','concepts'=>['context-clues-inference-clues','context-clues-contrast-clues','context-clues-definition-clues','text-structure-sequence','text-structure-problem-and-solution','text-structure-cause-and-effect','authors-purpose-and-tone-purpose','authors-purpose-and-tone-tone']],
            ['id'=>'composition-and-feedback','heading'=>'4. Composition, cohesion, and feedback','body'=>'A useful paragraph makes one claim, supports it with relevant detail, and explains why that detail matters. Cohesion comes from clear reference, logical sequencing, and transitions that accurately express the relationship between sentences. In a classroom response, feedback should point to the evidence or sentence move that needs revision and give the learner a chance to try again. A polished surface is not enough if the paragraph’s reasoning is unsupported; likewise, a useful draft can be improved without erasing the writer’s voice.','concepts'=>['cse-paragraph-organization','cse-paragraph-cohesion','cse-sentence-structure','cse-grammar-application']],
        ],
        'examples'=>[['heading'=>'Read a finding without overclaiming','prompt'=>'Learners compared two explanations using the same evidence, and most revised their original claim. What does this show?','steps'=>['Identify the observed action: learners compared explanations against evidence.','Identify the observed response: most revised their initial claim.','Avoid claiming that they permanently mastered the concept or that comparison alone caused the change.'],'answer'=>'The activity prompted evidence-based reconsideration rather than simple recall.','check'=>'The conclusion describes the observed reasoning behavior without making a causal or mastery claim.']],
        'misconceptions'=>['A single sentence can always establish a passage’s purpose.','A grammar edit is correct even if it changes the intended meaning.','A revised response proves durable learning without later evidence.'],
        'patterns'=>['Point to the exact sentence or detail supporting an inference.','Check the main subject and antecedent before revising.','Give feedback that names a next step the learner can perform.'],
        'questions'=>[['id'=>'90','section'=>'reading-claim-and-evidence','concept'=>'english-inference-evidence','sources'=>['prc-let-enhanced-tos-2025','deped-k12-english-curriculum-guide']]],
    ],
    [
        'id'=>'let-filipino-pagbasa-wika-at-pagsulat','board'=>'let','subject'=>'filipino','title'=>'LET Filipino: Pagbasa, Wastong Gamit, at Pagbuo ng Teksto','pdf'=>'let-filipino-pagbasa-wika-at-pagsulat.pdf',
        'scope'=>['prc-let-enhanced-tos-2025','prc-lept-alignment-guidance-2025'],'instruction'=>['deped-filipino-curriculum-guide','kwf-balarila-pambansa','kwf-diksiyonaryo'],
        'scope_note'=>'Ang saklaw ay ibabatay sa kasalukuyang PRC LEPT TOS at sa mga sanggunian ng DepEd at Komisyon sa Wikang Filipino. Orihinal ang mga paliwanag at halimbawa rito. Panimulang yunit lamang ito, hindi buong reviewer sa Filipino.',
        'objectives'=>['Matukoy ang pangunahing diwa at ebidensiya sa tekstong binasa.','Makabuo ng hinuha na hindi lumalampas sa impormasyong nasa teksto.','Maipaliwanag kung paanong ang gramatika, talasalitaan, at organisasyon ay lumilinaw sa kahulugan.'],
        'sections'=>[
            ['id'=>'pangunahing-diwa-at-ebidensiya','heading'=>'1. Pangunahing diwa at ebidensiya','body'=>'Basahin muna kung ang tanong ay tungkol sa tuwirang detalye, pangunahing diwa, layunin, o hinuha. Ang pangunahing diwa ang ideyang pinag-uugnay ng mahahalagang pangungusap; hindi ito basta pinakamadalas na salitang lumilitaw. Itala ang detalyeng sumusuporta rito at suriin kung talagang pinatutunayan ng detalye ang pahayag. Kapag may dalawang pagbabagong naganap kasabay ng pagtaas o pagbaba, huwag magtakda agad ng iisang sanhi kung walang paghahambing na naghihiwalay sa epekto.','concepts'=>['filipino-pagbasa-pangunahing-diwan','filipino-pagsulat-buod']],
            ['id'=>'hinuha-at-konteksto','heading'=>'2. Hinuha mula sa konteksto','body'=>'Ang hinuha ay konklusyong binubuo mula sa tekstuwal na pahiwatig at makatwirang ugnayan; hindi ito opinyong walang batayan. Hanapin ang pahayag, halimbawa, pangatnig, at kundisyong inilalahad ng may-akda. Pagkatapos, sabihin kung ano ang ipinahihiwatig at kung anong impormasyon ang hindi pa tiyak. Para sa salitang di-pamilyar, gamitin ang depinisyon, paghahambing, kasalungat, o halimbawa sa paligid nito. Kung may maraming posibleng kahulugan, tingnan ang gamit nito sa pangungusap at sumangguni sa mapagkakatiwalaang diksiyonaryo.','concepts'=>['filipino-talasalitaan-kasingkahulugan','filipino-talasalitaan-konteksto']],
            ['id'=>'wastong-gamit-at-estruktura','heading'=>'3. Wastong gamit, gramatika, at estruktura','body'=>'Suriin ang gampanin ng bawat salita sa pangungusap bago pumili ng anyo o pang-ugnay. Tingnan kung malinaw ang simuno at panaguri, kung ang panghalip ay may tiyak na tinutukoy, at kung lohikal ang ugnayan ng mga sugnay. Ang wastong gamit ay nakabatay sa kahulugan at tuntunin sa Filipino, hindi sa tuwirang paglilipat ng tuntunin sa Ingles. Gamitin ang Balarila at iba pang sanggunian bilang batayan, ngunit isaalang-alang din ang rehistro, konteksto, at layunin ng pahayag.','concepts'=>['filipino-gramatika-wastong-gamit','filipino-komunikasyon-angkop-na-wika']],
            ['id'=>'panitikan-at-organisadong-pagsulat','heading'=>'4. Panitikan at organisadong pagsulat','body'=>'Sa pagsusuri ng akda, ihiwalay ang nakikitang detalye sa interpretasyon: sino ang nagsasalaysay, ano ang nagaganap, anong tunggalian ang lumilitaw, at anong tema ang sinusuportahan ng mga pangyayari. Isaalang-alang ang panahon, pamayanan, at pananaw nang hindi ipinapalagay na iisa ang karanasan ng lahat. Sa buod, piliin lamang ang mahahalagang ideya at panatilihin ang ugnayan ng mga ito; huwag magdagdag ng bagong paghuhusga. Sa talatang nagpapaliwanag, ayusin ang pahayag, patunay, at paliwanag sa lohikal na pagkakasunod-sunod.','concepts'=>['filipino-panitikan-tauhan','filipino-panitikan-tema','filipino-pagsulat-organisasyon']],
        ],
        'examples'=>[['heading'=>'Maingat na hinuha sa Filipino','prompt'=>'Tumaas ang pagdalo matapos ang paalala, ngunit kasabay nito ay nagbago ang iskedyul. Ano ang pinakamaingat na hinuha?','steps'=>['Itala ang dalawang pagbabagong kasabay ng pagtaas: paalala at iskedyul.','Suriin kung may paghahambing na naghihiwalay sa epekto ng bawat pagbabago.','Piliin ang konklusyong nagsasabi lamang ng nasusuportahan ng tala.'],'answer'=>'Tumaas ang pagdalo kasabay ng dalawang pagbabago; hindi matitiyak ang hiwalay na epekto.','check'=>'Hindi tinutukoy ng tala kung alin sa dalawang pagbabago ang sanhi ng pagtaas.']],
        'misconceptions'=>['Ang pangunahing diwa ay kapareho ng isang detalyeng kawili-wili.','Ang hinuha ay maaaring magdagdag ng impormasyong wala sa teksto.','Maaaring ipalit nang direkta sa Filipino ang tuntunin sa Ingles.'],
        'patterns'=>['Tukuyin ang uri ng tanong bago pumili ng sagot.','Iugnay ang hinuha sa tiyak na pahiwatig.','Ihiwalay ang buod, interpretasyon, at sariling opinyon.'],
        'questions'=>[],
    ],
    [
        'id'=>'let-mathematics-models-and-quantitative-reasoning','board'=>'let','subject'=>'mathematics','title'=>'LET Mathematics: Number Sense, Models, and Data Reasoning','pdf'=>'let-mathematics-models-and-quantitative-reasoning.pdf',
        'scope'=>['prc-let-enhanced-tos-2025','prc-lept-alignment-guidance-2025'],'instruction'=>['openstax-precalculus-2e','openstax-calculus-volume-1','nist-semtech-engineering-statistics-handbook'],
        'scope_note'=>'The PRC LEPT TOS and DepEd Mathematics curriculum are the scope references. This lesson teaches selected quantitative reasoning with original numbers; check the current curriculum and examination documents before treating it as a complete specialization guide.',
        'objectives'=>['Choose an operation and representation that fits a word problem.','Solve and check a one-variable equation or proportional relationship.','Summarize and compare data using the correct unit and baseline.'],
        'sections'=>[
            ['id'=>'number-sense-and-units','heading'=>'1. Number sense, operations, and units','body'=>'Estimate before calculating so an answer with an impossible sign or scale is easy to notice. Keep the unit attached to each quantity and convert to a common unit before adding or comparing. Fractions, decimals, and percentages are alternate representations of a relationship; choose the one that makes the calculation transparent. In multi-step problems, state what each intermediate value represents instead of copying numbers into an unexplained expression. A reasonable estimate and a reverse check can reveal errors that a calculator will not.','concepts'=>['math-number-sense-operations','math-number-sense-fractions','math-measurement-unit-conversion']],
            ['id'=>'equations-functions-and-models','heading'=>'2. Equations, patterns, and functions','body'=>'Translate a verbal condition into an equation by naming the unknown and defining each term. Solve with equivalent operations, then substitute the result into the original statement. A pattern suggests a rule; verify the rule against every given term before extending it. A function describes how an output depends on an input under a defined relationship, and a graph can show where the relationship rises, falls, or changes. Distinguish a model’s prediction from an observed measurement, and state the range where the model makes sense.','concepts'=>['math-algebra-linear-equations','math-algebra-patterns','math-algebra-functions','math-problem-solving-modeling']],
            ['id'=>'geometry-and-measurement','heading'=>'3. Geometry and measurement','body'=>'Geometry problems are easier when you draw and label the figure before selecting a formula. Identify the requested quantity—length, perimeter, area, angle, or volume—and check that the formula matches the shape. Use the stated units consistently and remember that area uses square units. A diagram may not be drawn to scale, so use the given measurements and relationships rather than visual appearance. For angle or shape relationships, write the rule that connects the parts and test whether the values meet the full condition.','concepts'=>['math-geometry-area-perimeter','math-geometry-angle-relationships','math-measurement-unit-conversion']],
            ['id'=>'statistics-and-data-comparison','heading'=>'4. Summaries, probability, and data','body'=>'Before summarizing a data set, identify the population or sample, variable, and unit of observation. The mean uses all values and can move under an extreme observation; the median is the middle ordered value and may better represent a skewed set. Probability describes a defined event within a stated sample space; it is not a guarantee about one outcome. When comparing totals or rates, use the same time window and denominator. Explain what the data support and avoid extending the result to a population or cause that was not studied.','concepts'=>['math-number-sense-operations','math-statistics-mean-median','math-statistics-probability','math-problem-solving-modeling']],
        ],
        'examples'=>[['heading'=>'Compare time totals','prompt'=>'Reading takes 30, 40, and 35 minutes over three days; practice takes 20, 15, and 25 minutes; review takes 10, 15, and 20 minutes. Which total is largest, and by how much over the second largest?','steps'=>['Reading: 30 + 40 + 35 = 105 minutes.','Practice: 20 + 15 + 25 = 60; review: 10 + 15 + 20 = 45.','Compare the totals and subtract 105 − 60 = 45.'],'answer'=>'Reading is largest, by 45 minutes over practice.','check'=>'All three totals use the same unit and three-day period.']],
        'misconceptions'=>['An answer that looks reasonable needs no unit or reverse check.','A graph’s visual scale replaces the values and labels.','The mean and median always describe a data set equally well.'],
        'patterns'=>['Name the unknown and units before writing an equation.','Check a solution in the original condition.','Compare like units, periods, and denominators.'],
        'questions'=>[['id'=>'21','section'=>'statistics-and-data-comparison','concept'=>'math-number-sense-operations','sources'=>['prc-let-enhanced-tos-2025','openstax-precalculus-2e']]],
    ],
    [
        'id'=>'let-science-inquiry-systems-and-evidence','board'=>'let','subject'=>'science','title'=>'LET Science: Inquiry, Systems, and Evidence-Based Explanations','pdf'=>'let-science-inquiry-systems-and-evidence.pdf',
        'scope'=>['prc-let-enhanced-tos-2025','prc-lept-alignment-guidance-2025'],'instruction'=>['deped-science-curriculum-guide','openstax-biology-2e','openstax-chemistry-2e','openstax-university-physics-volume-1'],
        'scope_note'=>'DepEd’s K–12 Science curriculum emphasizes scientific knowledge, process skills, and evidence-based explanations across life science, chemistry, physics, and Earth science. This lesson covers selected competencies and is not a substitute for the current PRC TOS or full curriculum guide.',
        'objectives'=>['Distinguish an observation from an inference and a testable question.','Explain diffusion using particle movement and a concentration gradient.','Use a model and evidence to interpret motion or an Earth/life-science pattern.'],
        'sections'=>[
            ['id'=>'inquiry-variables-and-evidence','heading'=>'1. Inquiry, variables, and evidence','body'=>'A scientific explanation connects observations to a model and makes clear what evidence could support or challenge it. In an investigation, define the question, independent variable, measured outcome, and conditions held comparable. Repeat measurements where appropriate and record uncertainty rather than hiding variation. A conclusion should follow from the data and design; a single uncontrolled observation rarely establishes cause. Models are useful representations, not literal copies of nature, and their limits should be stated when applying them to a new situation.','concepts'=>['science-inquiry-evidence','science-data-evidence']],
            ['id'=>'cells-matter-and-transport','heading'=>'2. Cells, particles, and movement across membranes','body'=>'Particles in matter are in continuous motion. Diffusion is the net movement of particles from a region of higher concentration toward lower concentration; it does not require a cell to spend energy for that net movement. Osmosis refers specifically to water moving across a selectively permeable membrane under a concentration difference. Active transport uses cellular energy to move substances against a gradient. A diagram should be read for what is moving, which direction it moves, and whether energy is shown before choosing a process name.','concepts'=>['science-biology-cells','science-chemistry-matter-particles']],
            ['id'=>'motion-forces-and-energy','heading'=>'3. Motion, forces, and energy models','body'=>'Position change over time describes motion; a distance–time or position–time graph shows how that change varies. The slope of a position–time graph represents velocity under the graph’s chosen axes. A net force changes an object’s motion, while balanced forces can coexist with motion at constant velocity. Energy accounting tracks transfers and transformations without treating energy as destroyed in an ideal closed model. Check sign, unit, direction, and the conditions of a model before interpreting a graph or calculation.','concepts'=>['science-physics-motion-graphs','science-physics-force-balance','science-electricity-series-parallel','science-optics-reflection']],
            ['id'=>'earth-life-and-environmental-systems','heading'=>'4. Earth, ecosystems, and environmental reasoning','body'=>'Earth and life-science patterns reflect interacting systems. Relative rock-layer order can support an age sequence where the layers have not been disturbed, but it does not by itself provide a calendar date. In an ecosystem, energy flows through trophic relationships while matter cycles; population patterns depend on resources, interactions, and environmental conditions. Environmental claims should identify the measured outcome, spatial scale, and time period, then distinguish evidence from a proposed cause. Connect local examples to the curriculum without assuming one community represents all settings.','concepts'=>['science-earth-stratigraphy','science-ecology-population','cse-environmental-public-interest','environmental-stewardship-protection']],
        ],
        'examples'=>[['heading'=>'Identify movement across a membrane','prompt'=>'Particles move from higher concentration to lower concentration across a selectively permeable membrane, with no energy input. Which process is illustrated?','steps'=>['Identify the substance as particles; the prompt does not specify water alone.','Note the net direction is down the concentration gradient.','Check that no energy input is described.'],'answer'=>'Simple diffusion.','check'=>'If the moving substance were specifically water, osmosis would be the more specific term; movement against a gradient would require another explanation.']],
        'misconceptions'=>['Every movement across a membrane is osmosis.','A model or graph is a literal record of all conditions.','An observed association alone identifies the cause.'],
        'patterns'=>['Name the observation before the interpretation.','Read graph axes and units before inferring change.','State one limitation of the experiment or model.'],
        'questions'=>[['id'=>'31','section'=>'cells-matter-and-transport','concept'=>'science-biology-cells','sources'=>['prc-let-enhanced-tos-2025','deped-science-curriculum-guide','openstax-biology-2e']]],
    ],
    [
        'id'=>'let-social-studies-source-civic-and-historical-reasoning','board'=>'let','subject'=>'social-studies','title'=>'LET Social Studies: Historical Sources, Civic Duties, and Context','pdf'=>'let-social-studies-source-civic-and-historical-reasoning.pdf',
        'scope'=>['prc-let-enhanced-tos-2025','prc-lept-alignment-guidance-2025'],'instruction'=>['deped-araling-panlipunan-curriculum-guide','1987-philippine-constitution','nhcp-rizal-memory-collection','republic-act-10533'],
        'scope_note'=>'The PRC LEPT TOS and DepEd Araling Panlipunan curriculum guide inform the scope. This original unit teaches source analysis, civic reasoning, and historical context; its examples do not claim to cover all Philippine history or social-science topics.',
        'objectives'=>['Assess a historical source by origin, audience, time, and purpose.','Separate a claim from the evidence and context that support it.','Connect civic duties or rights to an appropriate primary source.'],
        'sections'=>[
            ['id'=>'historical-source-provenance','heading'=>'1. Historical sources and provenance','body'=>'A primary source was created in the period or context being studied, but it is not automatically complete or unbiased. Ask who created it, when, for whom, why, and what the creator could directly observe. A later textbook is a secondary account that may synthesize many sources; it also has an author, evidence base, and interpretive purpose. When accounts disagree, compare provenance and look for independent corroboration before deciding which claim is better supported. Keep what a source says distinct from what the historian infers from it.','concepts'=>['social-history-primary-sources','social-history-context-and-causation','let-rizal-context']],
            ['id'=>'historical-change-and-perspective','heading'=>'2. Context, change, and multiple perspectives','body'=>'Historical explanation connects people’s choices to institutions, resources, beliefs, geography, and events at a particular time. Avoid explaining the past only through today’s categories or assuming that a single group experienced an event uniformly. Compare perspectives and consequences, identify what changed and what persisted, and ask whose account is missing from the available record. A causal claim should identify a mechanism and support it with evidence that addresses plausible alternatives. Context helps explain a choice without automatically excusing or condemning it.','concepts'=>['social-history-context-and-causation','let-global-local-effects','let-self-identity']],
            ['id'=>'civic-rights-duties-and-public-good','heading'=>'3. Civic rights, duties, and the public good','body'=>'Civic questions should be grounded in the relevant constitutional text, law, institution, and facts. Identify which right, duty, or public responsibility is involved and who has authority to act. The phrase “public good” does not erase individual rights or replace fair process. For an environmental or community issue, name the affected group, observed condition, applicable source, and decision process. Distinguish an ethical recommendation from a legal requirement, and verify current rules before interpreting a real case.','concepts'=>['social-civics-public-good','cse-constitutional-principles','social-civics-rights-and-duties','social-civics-evidence-and-claims','let-ethical-duties']],
        ],
        'examples'=>[['heading'=>'Resolve a discrepancy in two accounts','prompt'=>'A diary and a later textbook disagree about when a bridge closed. What should a historian do first?','steps'=>['Record the creation date, author, audience, and purpose of each account.','Check whether the diary writer directly observed the closure and what “closed” means in context.','Compare independent dated records, such as notices, maps, or local reports.'],'answer'=>'Compare dates, context, and other records before resolving the discrepancy.','check'=>'Neither a contemporary diary nor a later textbook is automatically decisive.']],
        'misconceptions'=>['A primary source is always more accurate than a later synthesis.','Historical context is an excuse rather than an explanatory frame.','A civic principle identifies the exact law and decision-maker.'],
        'patterns'=>['Evaluate provenance before using a source as evidence.','Name a missing perspective or corroborating record.','Cite the specific civic authority relevant to a scenario.'],
        'questions'=>[['id'=>'41','section'=>'historical-source-provenance','concept'=>'social-history-primary-sources','sources'=>['prc-let-enhanced-tos-2025','deped-araling-panlipunan-curriculum-guide','nhcp-rizal-memory-collection']]],
    ],
    [
        'id'=>'let-tle-safety-competency-and-practice','board'=>'let','subject'=>'technology-and-livelihood-education','title'=>'LET TLE: Safety, Measurement, Competency, and Applied Practice','pdf'=>'let-tle-safety-competency-and-practice.pdf',
        'scope'=>['prc-let-enhanced-tos-2025','prc-lept-alignment-guidance-2025'],'instruction'=>['deped-epp-tle-curriculum-guide','tesda-competency-standards','tesda-training-regulations-index','ra-11058-occupational-safety','dole-do-252-25-osh-revised-irr-ra-11058'],
        'scope_note'=>'PRC’s LEPT TOS and DepEd EPP/TLE curriculum define the teacher-education scope; TESDA standards and training regulations describe particular vocational qualifications and assessment arrangements. This lesson covers shared applied principles, not every AFA, HE, ICT, and Industrial Arts specialization or a substitute for current occupational-safety rules.',
        'objectives'=>['Identify a hazard and select controls before beginning a task.','Use measurement and quality evidence to check a work product.','Describe competency as observable performance under stated conditions.'],
        'sections'=>[
            ['id'=>'hazard-identification-and-controls','heading'=>'1. Safety starts with the hazard','body'=>'Before choosing a tool or procedure, inspect the workspace and identify the hazard, who may be exposed, and how harm could occur. Apply appropriate controls in a deliberate order, use required personal protective equipment, keep the work area organized, and stop when conditions are unsafe. A warning sign or checklist alone does not remove a hazard. Actual workplace requirements depend on current Philippine law, the applicable DOLE rules, equipment instructions, and the task risk assessment; verify those sources before making a compliance claim.','concepts'=>['tle-occupational-safety','tle-ia-tools-and-machines-safety']],
            ['id'=>'measurement-quality-and-process','heading'=>'2. Measurement, quality, and process control','body'=>'A measurement needs a defined feature, unit, instrument, and tolerance or acceptance criterion. Check the instrument’s condition and resolution, use it consistently, and record the result rather than rounding away a meaningful difference. Quality control compares evidence from the product or process with the stated requirement and triggers investigation when they differ. Do not call a result acceptable without a criterion, and do not treat a single measurement as proof that every item in a batch conforms.','concepts'=>['tle-measurement-and-quality','tle-ia-technical-drawing','tle-ia-materials-and-processes']],
            ['id'=>'competency-demonstration-and-feedback','heading'=>'3. Competency-based teaching and assessment','body'=>'A competency statement describes work a learner can demonstrate under defined conditions and to a stated performance standard. TESDA Training Regulations provide qualification-specific competency standards and assessment arrangements; a school lesson should not claim that one activity grants a TESDA qualification. Teach the process through explanation, demonstration, guided practice, feedback, and a performance task. Collect evidence that the learner can repeat the safe, accurate process, then target feedback to the missing step rather than awarding competence for attendance alone.','concepts'=>['tle-design-process','tle-technology-literacy','tle-resource-and-entrepreneurship']],
            ['id'=>'specialization-context-and-transfer','heading'=>'4. Transfer principles across TLE specializations','body'=>'Agriculture, home economics, ICT, and industrial arts use different tools, materials, risks, and technical standards. Shared habits—plan, identify risk, select resources, measure, document, evaluate quality, and reflect on improvement—transfer, but the specific procedure does not. For example, an ICT network task needs privacy and cybersecurity checks, while food preparation needs hygienic handling and a machine operation needs guarding and energy isolation. Consult the current DepEd curriculum and the matching TESDA or occupational reference for the specialization actually being taught.','concepts'=>['tle-afa-crop-production','tle-he-food-preparation-and-safety','tle-ict-digital-citizenship','tle-ia-basic-electricity','tle-ia-carpentry-and-construction']],
        ],
        'examples'=>[['heading'=>'Choose a safe first action','prompt'=>'Before selecting a tool, a learner notices an exposed conductor and a wet work surface. What is the responsible first step?','steps'=>['Stop the task and keep people away from the immediate hazard.','Follow the applicable isolation and reporting procedure; do not touch the conductor or assume the area is safe.','Have the responsible qualified person verify controls before work resumes.'],'answer'=>'Stop and control the hazard before choosing or using a tool.','check'=>'This learning example is not a substitute for site-specific emergency procedures or current occupational-safety requirements.']],
        'misconceptions'=>['Wearing PPE alone makes every tool operation safe.','Attendance or a written quiz proves practical competency.','A shared core process is enough to teach every TLE specialization.'],
        'patterns'=>['Identify hazard, control, and verification before task steps.','State the measurement criterion and instrument.','Match performance evidence to the specific competency.'],
        'questions'=>[['id'=>'6018','section'=>'hazard-identification-and-controls','concept'=>'tle-occupational-safety','sources'=>['prc-let-enhanced-tos-2025','deped-epp-tle-curriculum-guide','ra-11058-occupational-safety']]],
    ],
    [
        'id'=>'me-machine-design-stress-materials-and-shop','board'=>'mechanical-engineering','subject'=>'machine-design-materials-shop-practice','title'=>'Machine Design: Stress, Materials, Measurement, and Shop Practice','pdf'=>'me-machine-design-stress-materials-and-shop.pdf',
        'scope'=>['prc-mechanical-engineering-2026-program'],'instruction'=>['open-mechanical-design-manufacturing','open-manufacturing-processes-4-5','openstax-university-physics-volume-1','nist-semtech-engineering-statistics-handbook'],
        'scope_note'=>'The PRC August 2026 MELE program identifies Machine Design, Materials and Shop Practice as a distinct subject. This guide teaches selected mechanics and design reasoning; it does not provide current code allowables, certify a component, or cover every manufacturing process.',
        'objectives'=>['Resolve a force into components and maintain equilibrium.','Use section modulus for an idealized bending-stress estimate.','Select a material or manufacturing check using stated requirements and evidence.'],
        'sections'=>[
            ['id'=>'forces-and-load-paths','heading'=>'1. Forces, moments, and load paths','body'=>'Begin a machine-element problem with a free-body diagram that shows applied loads, supports, geometry, and axes. Resolve a force into components using the angle’s stated reference direction, then apply force and moment equilibrium. Trace the load through connected parts so the analysis includes the shaft, key, fastener, bearing, and housing that carry the action. A force component has the same units as the original force, and a moment has force times distance. A correct diagram often prevents a sign or geometry error before calculation begins.','concepts'=>['b644-me-engineering-mechanics','b644-me-machine-power-transmission','b644-me-mechanism-kinematics']],
            ['id'=>'stress-fatigue-and-stability','heading'=>'2. Stress, fatigue, and stability','body'=>'For a rectangular section bent about its strong axis, the elastic section modulus is S = bd²/6 and the elementary bending-stress magnitude is σ = M/S. The result depends on orientation, units, elastic behavior, and a suitable beam model. Repeated or fluctuating loads introduce fatigue questions; slender compression members may need a stability analysis rather than a simple material-strength comparison. A factor of safety or allowable value must come from the applicable design basis, not from an invented universal number. Separate a classroom stress estimate from a complete component design.','concepts'=>['b644-me-machine-design-stress-analysis','b644-me-stability-fatigue','b644-me-pressure-components']],
            ['id'=>'materials-metrology-and-manufacturing','heading'=>'3. Materials, tolerances, and manufacturing','body'=>'Material choice should follow the service environment, loading, temperature, wear, corrosion, manufacturability, and inspection plan. A material label alone does not establish the condition, heat treatment, or measured property of a specific component. Tolerances define acceptable variation; fits relate mating dimensions and assembly function. Select a measurement method with suitable range and resolution, then record the datum, temperature or setup when relevant, and observed value. Manufacturing processes introduce characteristic surface, dimensional, and defect risks that should be inspected against the drawing and acceptance criteria.','concepts'=>['b644-me-materials-properties','b644-me-tolerances-metrology','b644-me-manufacturing-shop-practice','b644-me-engineering-drawing-practice']],
            ['id'=>'maintenance-quality-and-shop-safety','heading'=>'4. Quality, maintenance, and shop safety','body'=>'Reliability and maintenance decisions use failure history, operating conditions, criticality, and inspection evidence. A failure mode helps organize cause and consequence, but a ranking tool is only as good as the team’s evidence and assumptions. Before maintenance or machining, identify stored energy and hazardous motion, isolate equipment under the applicable workplace procedure, and verify the safe state. Shop practice also includes guarding, correct tooling, housekeeping, and material handling. Verify current Philippine occupational-safety rules and machine instructions; this general discussion does not prescribe a site-specific control plan.','concepts'=>['b644-me-quality-reliability-maintenance','b644-me-shop-safety-practice','b644-me-production-systems','b644-me-bearings-lubrication']],
        ],
        'examples'=>[['heading'=>'Estimate elastic bending stress','prompt'=>'A rectangular section is 0.10 m wide and 0.20 m deep under a 2 kN·m bending moment. Using S = bd²/6, estimate the bending stress.','steps'=>['Compute S = 0.10(0.20²)/6 = 0.0006667 m³.','Convert moment to N·m: M = 2,000 N·m.','Compute σ = M/S = 2,000/0.0006667 ≈ 3.0 × 10⁶ N/m².'],'answer'=>'Approximately 3 MPa under the stated elastic bending model.','check'=>'The result is a nominal stress estimate; it does not include stress concentrations, fatigue, shear, or design allowables.']],
        'misconceptions'=>['A large calculated safety factor makes assumptions irrelevant.','A nominal material grade proves a component’s installed condition.','One average stress captures fatigue and local stress concentration.'],
        'patterns'=>['Draw the load path and resolve components before calculating.','Confirm the section axis and units in a bending calculation.','Match inspection evidence to the drawing requirement.'],
        'questions'=>[['id'=>'1404','section'=>'stress-fatigue-and-stability','concept'=>'b644-me-machine-design-stress-analysis','sources'=>['prc-mechanical-engineering-2026-program','open-mechanical-design-manufacturing']]],
    ],
    [
        'id'=>'me-mathematics-engineering-models-and-units','board'=>'mechanical-engineering','subject'=>'mathematics','title'=>'Mechanical Engineering Mathematics: Vectors, Models, and Data','pdf'=>'me-mathematics-engineering-models-and-units.pdf',
        'scope'=>['prc-mechanical-engineering-2026-program'],'instruction'=>['openstax-precalculus-2e','openstax-calculus-volume-1','nist-semtech-engineering-statistics-handbook','ualberta-introduction-engineering-economics'],
        'scope_note'=>'PRC’s current MELE program identifies Mathematics as a separate subject. This lesson provides selected mathematical foundations and model checks; it is not a complete mathematics syllabus or a replacement for the current PRC scope.',
        'objectives'=>['Represent perpendicular vector components and calculate a resultant.','Choose an equation, function, or derivative that represents the stated model.','Check units, numerical scale, and data interpretation before reporting a result.'],
        'sections'=>[
            ['id'=>'vectors-and-coordinate-models','heading'=>'1. Vectors and coordinate models','body'=>'A vector has magnitude and direction. Resolve it into components along a defined coordinate system before combining it with other vectors. Perpendicular components form a right triangle, while nonperpendicular components require the appropriate trigonometric or vector operation. Distinguish a displacement vector from the total path length: they answer different questions. State the positive axis directions, preserve units, and check whether a sign indicates direction rather than a negative physical magnitude.','concepts'=>['b644-me-math-vectors-linear-algebra','b644-me-math-analytic-geometry']],
            ['id'=>'algebra-calculus-and-differential-models','heading'=>'2. Algebra, calculus, and differential models','body'=>'Algebra solves relationships under equivalent transformations; substitute a solution into the original equation to catch sign and arithmetic errors. A function represents how an output depends on an input, while a derivative describes local rate of change under the chosen variables. Definite integration can accumulate a rate over an interval. A differential equation connects a quantity and its rates of change, and its solution depends on the model and initial or boundary conditions. Check domain, units, and assumptions before interpreting a symbolic result physically.','concepts'=>['b644-me-math-algebra-trigonometry','b644-me-math-calculus-models','b644-me-basic-engineering-sciences','b644-me-strength-materials']],
            ['id'=>'statistics-numerical-methods-and-economics','heading'=>'3. Statistics, numerical methods, and economics','body'=>'A data summary depends on how observations were collected and what population they represent. Use a suitable measure of center and spread, inspect plots and outliers, and distinguish association from causation. Numerical methods approximate solutions; report method, tolerance, convergence check, and the effect of rounding. Engineering economics compares alternatives over time with compatible cash-flow timing and stated assumptions about service, cost, and interest. A calculated ranking is conditional on those inputs and should not be presented as a universal preference.','concepts'=>['b644-me-math-statistics-numerical-methods','b644-me-engineering-economics']],
            ['id'=>'engineering-science-and-dimensional-checks','heading'=>'4. Engineering science and dimensional checks','body'=>'Dimensional analysis tests whether both sides of an equation have compatible physical dimensions and can reveal a missing conversion or exponent. It cannot prove a model is physically appropriate, so pair it with a free-body diagram, energy balance, or governing relationship. Track base and derived units throughout calculations. For stress, pressure, flow, and temperature, check the exact definition and reference state rather than relying on a familiar symbol. A result should be interpreted in its physical context and validated against a limiting case when possible.','concepts'=>['b644-me-basic-engineering-sciences','b644-me-fluid-mechanics','b644-me-thermodynamics']],
        ],
        'examples'=>[['heading'=>'Find a displacement resultant','prompt'=>'A survey robot moves 3 m east and then 4 m north. What is its straight-line displacement magnitude?','steps'=>['Represent the components as 3 m east and 4 m north.','The directions are perpendicular, so use the Pythagorean relation.','Magnitude = √(3² + 4²) = √25 m.'],'answer'=>'5 m.','check'=>'The path length is 3 + 4 = 7 m, which is different from the straight-line displacement.']],
        'misconceptions'=>['Vector components can be added without a common coordinate system.','A numerical approximation is exact because a calculator displayed digits.','Dimensional consistency proves the model assumptions are valid.'],
        'patterns'=>['Define axes and units before manipulating vectors.','Substitute algebraic answers back into the original relationship.','State the assumptions behind a numerical or economic comparison.'],
        'questions'=>[['id'=>'1379','section'=>'vectors-and-coordinate-models','concept'=>'b644-me-math-vectors-linear-algebra','sources'=>['prc-mechanical-engineering-2026-program','openstax-precalculus-2e']]],
    ],
    [
        'id'=>'me-power-plant-energy-cycles-and-heat-transfer','board'=>'mechanical-engineering','subject'=>'power-plant-engineering','title'=>'Power Plant Engineering: Energy Balances, Cycles, and Heat Transfer','pdf'=>'me-power-plant-energy-cycles-and-heat-transfer.pdf',
        'scope'=>['prc-mechanical-engineering-2026-program'],'instruction'=>['ubc-introduction-engineering-thermodynamics','openstax-university-physics-volume-2','doe-hydropower-how-it-works'],
        'scope_note'=>'The August 2026 PRC MELE program assigns Power Plant Engineering its own subject and relative weight. This lesson teaches selected energy and heat-transfer reasoning; actual plant operation, safety, emissions, and design require current applicable rules and qualified engineering review.',
        'objectives'=>['Apply an energy balance with a clearly defined system boundary.','Calculate heat transfer through series thermal resistances.','Compare cycle performance without confusing ideal and actual plant behavior.'],
        'sections'=>[
            ['id'=>'system-boundary-and-energy-balance','heading'=>'1. System boundaries and energy balances','body'=>'Choose the system boundary before writing an energy balance. For a steady-flow device, account for heat transfer, shaft work, mass flow, and changes in enthalpy, kinetic energy, and potential energy as relevant. State whether a term is neglected and why. A boiler, turbine, condenser, pump, and feedwater path have different energy interactions even though they belong to one plant. Keep mass and energy balances distinct, preserve consistent units, and compare the computed result with the expected direction of heat or work transfer.','concepts'=>['b644-me-power-cycles','b644-me-steam-power-boilers','b644-me-internal-combustion-engines','b644-me-gas-combined-cycle']],
            ['id'=>'heat-transfer-resistance','heading'=>'2. Heat transfer and thermal resistance','body'=>'For a steady one-dimensional resistance model, heat rate equals temperature difference divided by total thermal resistance. Series resistances add when the same heat rate passes through each layer and contact conditions fit the model. Parallel paths combine differently. The formula is an engineering analogy to conduction and does not by itself describe transient storage, radiation, convection correlations, or two-dimensional heat flow. Verify units: kelvins divided by kelvins per watt gives watts. Check whether surface and fluid-film resistances are included in the stated data.','concepts'=>['b644-me-heat-transfer']],
            ['id'=>'cycles-efficiency-and-plant-performance','heading'=>'3. Cycles, efficiency, and plant performance','body'=>'A thermal cycle converts supplied heat into work while rejecting some energy to a lower-temperature sink. Thermal efficiency is net useful work divided by heat input for the stated boundary and cycle. Ideal cycle relations help compare limits; actual performance also reflects component inefficiency, pressure drop, heat loss, off-design operation, and auxiliary loads. Compare efficiencies only when system boundaries and input definitions match. A plant heat rate or load curve may include operating constraints that a simple thermodynamic cycle omits.','concepts'=>['b644-me-power-cycles','b644-me-power-load-performance','b644-me-power-fuels-combustion']],
            ['id'=>'fluid-machinery-hvac-and-water-power','heading'=>'4. Fluid machinery, HVAC, and hydroelectric systems','body'=>'Pumps and turbines exchange shaft work with a fluid; their analysis relates flow, head, pressure, elevation, and losses. Fans and compressors also require a state model appropriate to the fluid and process. Refrigeration transfers heat from a colder region to a warmer one by supplying work; psychrometric loads depend on both temperature and moisture. Hydroelectric power draws on water flow and head, with conversion losses and environmental and operational constraints. Actual equipment selection requires system curves, operating ranges, manufacturer data, and applicable rules.','concepts'=>['b644-me-fluid-machinery','b644-me-hvac-refrigeration','b644-me-hydroelectric-plants']],
        ],
        'examples'=>[['heading'=>'Calculate heat rate across two resistances','prompt'=>'Two thermal resistances of 0.20 K/W and 0.30 K/W are in series across a 50 K temperature difference. Find the heat rate in the stated steady model.','steps'=>['Total resistance = 0.20 + 0.30 = 0.50 K/W.','Heat rate = ΔT/R = 50 K ÷ 0.50 K/W.','Check that units reduce to watts.'],'answer'=>'100 W.','check'=>'This assumes the supplied resistances are the complete series path and the process is steady.']],
        'misconceptions'=>['Cycle efficiency can be interpreted without defining heat input and work output.','Series and parallel thermal paths use the same resistance rule.','An ideal-cycle result predicts actual plant operation exactly.'],
        'patterns'=>['Draw the control volume and sign convention.','Write every resistance and its unit before combining.','Name losses and operating conditions omitted from an ideal model.'],
        'questions'=>[['id'=>'1398','section'=>'heat-transfer-resistance','concept'=>'b644-me-heat-transfer','sources'=>['prc-mechanical-engineering-2026-program','ubc-introduction-engineering-thermodynamics']]],
    ],
    [
        'id'=>'psych-assessment-evidence-validity-and-fair-use','board'=>'psychometrician','subject'=>'psychological-assessment','title'=>'Psychological Assessment: Evidence, Validity, and Responsible Use','pdf'=>'psych-assessment-evidence-validity-and-fair-use.pdf',
        'scope'=>['prc-psychometrician-enhanced-tos-2023'],'instruction'=>['apa-psychological-assessment-guidelines-2020','aera-apa-ncme-testing-standards-2014','openstax-psychology-2e','openstax-introductory-statistics-2e','lawphil-ra10029'],
        'scope_note'=>'PRC’s Psychologists and Psychometricians TOS is the examination-scope reference currently registered in this repository; currentness must be checked on the PRC board page before an exam. AERA/APA/NCME’s 2014 Standards remain versioned and the sponsors have begun revision work. This lesson is educational and not an individual test-interpretation or clinical recommendation.',
        'objectives'=>['Distinguish reliability evidence from validity evidence.','Explain a standard error of measurement in a hypothetical score example.','Select an assessment method in relation to purpose, population, context, and fairness.'],
        'sections'=>[
            ['id'=>'construct-purpose-and-validity','heading'=>'1. Construct, purpose, and validity evidence','body'=>'Start an assessment with the intended purpose and the construct or decision it is meant to inform. Validity concerns the evidence and theory supporting a particular interpretation and use of scores; it is not a permanent stamp attached to a test for every setting. Review content representation, response processes, internal structure, relationships with other variables, and consequences as relevant to the inference. A narrow sample of a broad trait can yield consistent scores while still leaving the intended construct underrepresented. State what the instrument can and cannot support.','concepts'=>['psych-assessment-properties-principles','psych-assessment-uses-limitations','psych-assessment-selection-tools']],
            ['id'=>'reliability-measurement-error-and-precision','heading'=>'2. Reliability, measurement error, and precision','body'=>'Reliability describes consistency under specified conditions, such as internal consistency, inter-rater agreement, or test–retest stability. It does not establish that a test measures the intended construct. Under classical test theory, a simplified standard error of measurement is SEM = SD × √(1 − r), where SD and reliability estimate r are appropriate to the same score interpretation. An SEM communicates expected score imprecision under the model; it is not a precise prediction for an individual’s true score. Report the reliability method, population, and context.','concepts'=>['psych-assessment-properties-principles','psych-assessment-research-statistics']],
            ['id'=>'selection-administration-and-interpretation','heading'=>'3. Select, administer, and interpret within scope','body'=>'Choose measures whose evidence fits the referral question, language, age, accessibility needs, population, and decision stakes. Standardized administration supports comparability, while accommodations may be needed to reduce construct-irrelevant barriers; document changes and interpret their effects. Review norms, scoring, confidence or uncertainty, and the limits of the reference group before comparing a person with others. Combine test results with interviews, records, observations, and relevant contextual evidence rather than treating one score as a complete description of a person.','concepts'=>['psych-assessment-administration-interpretation','psych-assessment-selection-tools','psych-assessment-uses-limitations']],
            ['id'=>'ethics-fairness-and-communication','heading'=>'4. Ethics, fairness, and communication','body'=>'Responsible assessment protects confidentiality, informed participation, test security, competence boundaries, and fair interpretation. Consider whether language, disability, culture, access, or testing conditions affect the inference. Explain findings in accessible terms, identify uncertainty, and make recommendations only within one’s competence and the instrument’s evidence. Legal scope in the Philippines is governed by the Psychology Act and current professional rules; standards from AERA, APA, and NCME are professional guidance, not Philippine statutes. Refer a question outside scope to the appropriate qualified professional.','concepts'=>['psych-assessment-ethics-standards','psych-assessment-uses-limitations']],
        ],
        'examples'=>[['heading'=>'Separate consistency from validity','prompt'=>'A stable trait is measured twice with the same test and the correlation is .88, but the test covers only one narrow part of the trait. What is best supported?','steps'=>['A high test–retest association supports temporal consistency under the sampled conditions.','Compare the test content with the full intended construct.','Do not infer broad validity from a reliability coefficient alone.'],'answer'=>'The test shows strong temporal reliability, while broader validity still needs evidence.','check'=>'Validity evidence must match the intended interpretation and use.']],
        'misconceptions'=>['A high reliability coefficient proves a measure is valid.','A standard error of measurement is a guaranteed individual interval.','A test result alone is a complete clinical or professional judgment.'],
        'patterns'=>['Name the interpretation and decision before reviewing the score.','Check population, method, and context for every coefficient.','Communicate limits, uncertainty, and referral needs.'],
        'questions'=>[['id'=>'1037','section'=>'reliability-measurement-error-and-precision','concept'=>'psych-assessment-properties-principles','sources'=>['prc-psychometrician-enhanced-tos-2023','aera-apa-ncme-testing-standards-2014','apa-psychological-assessment-guidelines-2020']]],
    ],
    [
        'id'=>'ree-professional-circuits-power-and-measurement','board'=>'registered-electrical-engineering','subject'=>'electrical-engineering-professional-subjects','title'=>'REE Professional Subjects: Circuits, Power, Machines, and Measurement','pdf'=>'ree-professional-circuits-power-and-measurement.pdf',
        'scope'=>['prc-ree-enhanced-tos-annex-a-2024','prc-ree-exam-program-september-2026'],'instruction'=>['mit-ocw-6-002-circuits-electronics','mit-ocw-6-061-electric-power-systems','mit-ocw-6-685-electric-machines','openstax-university-physics-volume-1'],
        'scope_note'=>'PRC’s enhanced REE TOS and September 2026 exam program are the official scope references. This guide develops selected electrical principles; current Philippine Electrical Code provisions, grid rules, equipment ratings, and safety requirements must be checked in the applicable current primary text.',
        'objectives'=>['Interpret a simple calibrated sensor relation and verify its units.','Explain how circuit, machine, and power-system models connect.','Recognize where a conceptual calculation stops and current code review begins.'],
        'sections'=>[
            ['id'=>'circuit-models-and-steady-state','heading'=>'1. Circuit models and steady-state reasoning','body'=>'A circuit model states element relations, connections, reference directions, and sources. Apply Kirchhoff’s current law at a node and voltage law around a loop, then check whether the solved currents and voltages satisfy each element relation. For sinusoidal steady state, phasors represent magnitude and phase at a common frequency; complex impedance allows resistive and reactive effects to be combined. Keep RMS and peak quantities distinct, use a consistent phase reference, and state the assumed frequency and linear model before interpreting the result.','concepts'=>['b633-ree-pro-dc-networks','b633-ree-pro-ac-impedance','b633-ree-pro-transients']],
            ['id'=>'power-machines-and-networks','heading'=>'2. Three-phase power, machines, and system behavior','body'=>'Three-phase quantities depend on whether the system and measurement are line-to-line or phase values and whether the connection is wye or delta. Power calculations require a consistent voltage, current, power-factor, and RMS convention. Transformers and rotating machines convert electrical and magnetic energy; equivalent circuits help analyze voltage, current, losses, torque, and speed within their assumptions. Power-system analysis adds network topology, operating conditions, demand, and fault behavior. Do not move from a simplified model to a field rating without equipment data and system studies.','concepts'=>['b633-ree-pro-three-phase','b633-ree-pro-transformers','b633-ree-pro-rotating-machines','b633-ree-pro-generators-conversion','b633-ree-pro-transmission-distribution','b633-ree-pro-power-analysis']],
            ['id'=>'instrumentation-control-and-calibration','heading'=>'3. Instrumentation, feedback, and calibration','body'=>'A measurement chain includes the physical quantity, sensor, conditioning, conversion, display or recording, and a calibration relationship. Check zero, span, units, range, resolution, uncertainty, and the conditions under which calibration was performed. Feedback compares a measured output with a reference and acts on the difference; stability and response depend on system dynamics and controller settings. For a linear calibration, use the supplied points only within the stated range unless linearity outside it is justified. A reading without an uncertainty or calibration context can overstate precision.','concepts'=>['b633-ree-allied-instrumentation','b633-ree-pro-control-systems']],
            ['id'=>'protection-utilization-and-current-rules','heading'=>'4. Protection, utilization, and current rules','body'=>'Protection coordinates detection and interruption of abnormal conditions while grounding and bonding manage fault-current paths and touch-risk. Wiring, illumination, and utilization choices depend on load characteristics, equipment, location, and the applicable code edition. Legal and professional responsibilities also matter: verify the current TOS, electrical law, Board issuances, Philippine Electrical Code provisions, and utility or grid requirements before stating a design limit. This lesson teaches how to identify the right check; it does not supply code tables or certify an installation.','concepts'=>['b633-ree-pro-protection-relaying','b633-ree-pro-wiring-utilization','b633-ree-pro-power-electronics','b633-ree-pro-telecommunications','b633-ree-pro-computer-power-applications']],
        ],
        'examples'=>[['heading'=>'Interpolate a sensor calibration','prompt'=>'A sensor calibration gives 1 V at 10 units and 3 V at 30 units. Assuming a linear relation over that interval, what voltage corresponds to 20 units?','steps'=>['The change is 2 V over 20 units, so the slope is 0.1 V per unit.','From 10 to 20 units is 10 units, adding 1 V to the 1 V reference.','Check that 20 units is between the two calibration points.'],'answer'=>'2.0 V under the stated linear interpolation assumption.','check'=>'This does not validate extrapolation outside the calibration interval or the sensor’s uncertainty.']],
        'misconceptions'=>['A calibration line is valid outside its measured range by default.','An RMS value and peak value can be substituted without conversion.','A calculation proves compliance with the current installation code.'],
        'patterns'=>['State reference direction, connection, and RMS convention.','Keep calibration range and uncertainty visible.','Name the primary code or system document needed for a compliance claim.'],
        'questions'=>[['id'=>'1620','section'=>'instrumentation-control-and-calibration','concept'=>'b633-ree-allied-instrumentation','sources'=>['prc-ree-enhanced-tos-annex-a-2024','mit-ocw-6-002-circuits-electronics']]],
    ],
    [
        'id'=>'ree-allied-mechanics-thermal-electronics-and-practice','board'=>'registered-electrical-engineering','subject'=>'engineering-sciences-and-allied-subjects','title'=>'REE Allied Subjects: Mechanics, Thermal Science, Electronics, and Practice','pdf'=>'ree-allied-mechanics-thermal-electronics-and-practice.pdf',
        'scope'=>['prc-ree-enhanced-tos-annex-a-2024','prc-ree-exam-program-september-2026'],'instruction'=>['openstax-university-physics-volume-1','openstax-university-physics-volume-2','openstax-chemistry-2e','mit-ocw-6-002-circuits-electronics','supreme-court-ra-7920-electrical-engineering-law'],
        'scope_note'=>'PRC’s enhanced REE TOS identifies engineering sciences and allied competencies. This lesson teaches selected mechanics, thermal, electronic, and professional foundations. Consult current statutes, regulations, standards, and the relevant discipline source before applying the examples to a real installation or project.',
        'objectives'=>['Apply Newton’s second law to a stated system.','Relate thermal and fluid quantities through a defined system model.','Explain basic semiconductor and professional-practice boundaries.'],
        'sections'=>[
            ['id'=>'mechanics-and-materials','heading'=>'1. Mechanics, free-body diagrams, and materials','body'=>'For a body of known mass, Newton’s second law relates net force to acceleration, Fnet = ma. Draw a free-body diagram that includes only forces acting on the selected system, choose axes, and keep each force component in newtons. Equal and opposite interaction forces act on different bodies, so they do not cancel on one body’s diagram. Materials behavior adds stress, strain, and temperature or time effects; use properties measured for the relevant condition rather than assuming one nominal value describes every specimen.','concepts'=>['b633-ree-allied-mechanics','b633-ree-allied-materials']],
            ['id'=>'thermodynamics-and-fluid-models','heading'=>'2. Thermodynamics, heat transfer, and fluid behavior','body'=>'A thermal analysis needs a system boundary, state properties, heat-transfer direction, and work terms. Energy balances track transfers and changes in state; heat is energy in transit, not a stored property. Fluid models relate pressure, density, velocity, elevation, and losses, with assumptions that vary between static fluids, idealized flows, and real networks. Check units and identify neglected terms before solving. A result from a simplified model should not be turned into an equipment rating without the appropriate data and standard.','concepts'=>['b633-ree-allied-thermodynamics','b633-ree-allied-fluid-mechanics']],
            ['id'=>'electronics-and-computing','heading'=>'3. Semiconductor, analog, digital, and computing foundations','body'=>'Electronic circuits use device models that are valid over particular bias and frequency ranges. A semiconductor junction or amplifier is not an ideal switch or gain block under every condition. Digital logic represents states using defined voltage thresholds and timing assumptions; conversion and measurement add resolution and quantization limits. For a programming or computer-application problem, define inputs, operations, expected outputs, and error cases before choosing an implementation. Verify behavior with a transparent test rather than trusting a plausible-looking output.','concepts'=>['b633-ree-allied-electronics-semiconductor','b633-ree-allied-electronics-analog','b633-ree-allied-electronics-digital','b633-ree-allied-computer-programming']],
            ['id'=>'law-safety-and-professional-boundaries','heading'=>'4. Law, contracts, safety, and professional boundaries','body'=>'Republic Act No. 7920 defines the Philippine legal framework for electrical engineering practice and professional registration; current regulations and Board issuances add detail. A contract or specification communicates scope and obligations but does not replace safety duties or the current code. Identify who has authority, what work is within competence, which document version controls, and who must approve a deviation. For safety, follow the current Philippine occupational-safety rules and project procedures; this lesson does not provide a site-specific hazard assessment or legal opinion.','concepts'=>['b633-ree-allied-safety-code','b633-ree-allied-law-code-ethics','b633-ree-allied-contracts-specifications']],
        ],
        'examples'=>[['heading'=>'Find net force from acceleration','prompt'=>'A 10 kg instrument carriage accelerates at 2 m/s². What net force acts on the carriage?','steps'=>['Identify mass m = 10 kg and acceleration a = 2 m/s².','Apply Fnet = ma = 10 × 2.','Check units: kg·m/s² = N.'],'answer'=>'20 N in the direction of the acceleration.','check'=>'This is the net force; the applied force may be different when friction or other forces act.']],
        'misconceptions'=>['A force pair on interacting bodies cancels on one free-body diagram.','A semiconductor model works outside its stated range.','A project specification overrides a safety law or professional scope boundary.'],
        'patterns'=>['Draw a system boundary and free-body diagram first.','State idealizations and omitted losses.','Check authority, version, and competence for a professional decision.'],
        'questions'=>[['id'=>'1605','section'=>'mechanics-and-materials','concept'=>'b633-ree-allied-mechanics','sources'=>['prc-ree-enhanced-tos-annex-a-2024','openstax-university-physics-volume-1']]],
    ],
    [
        'id'=>'ree-mathematics-linear-systems-complex-models-and-data','board'=>'registered-electrical-engineering','subject'=>'registered-electrical-engineering-mathematics','title'=>'REE Mathematics: Linear Systems, Complex Models, and Data','pdf'=>'ree-mathematics-linear-systems-complex-models-and-data.pdf',
        'scope'=>['prc-ree-enhanced-tos-annex-a-2024','prc-ree-exam-program-september-2026'],'instruction'=>['openstax-precalculus-2e','openstax-calculus-volume-1','mit-ocw-18-03sc-fourier-laplace','nist-semtech-engineering-statistics-handbook'],
        'scope_note'=>'PRC’s current REE TOS and examination program guide subject scope. This original module connects selected algebra, calculus, phasor, transform, probability, and economic methods; it is not a complete REE mathematics course.',
        'objectives'=>['Solve a simultaneous linear model and verify every original equation.','Relate derivatives and differential equations to change over time.','Explain when complex and transform methods represent periodic or dynamic behavior.'],
        'sections'=>[
            ['id'=>'linear-systems-and-matrices','heading'=>'1. Linear equations, matrices, and determinants','body'=>'A system of linear equations represents several constraints on the same unknowns. Elimination, substitution, or matrix methods can solve the system when the coefficient structure supports a unique solution. After calculating, substitute the result into every original equation; a check can reveal arithmetic or transcription errors. A determinant helps diagnose invertibility for a square matrix, but numerical conditioning matters when inputs are approximate. In an engineering interpretation, variables retain their units and the equations must represent compatible physical relationships.','concepts'=>['b633-ree-math-algebra-linear','b633-ree-math-matrices-determinants']],
            ['id'=>'calculus-and-differential-equations','heading'=>'2. Calculus, rates, and differential equations','body'=>'A derivative models instantaneous change with respect to a defined variable; its units are the dependent quantity’s units divided by the independent quantity’s units. Integration accumulates a rate over an interval, subject to bounds and initial conditions. Differential equations express how a system’s state changes and require conditions that identify a particular solution. Interpret an equation alongside the physical meaning of its variables and sign convention; a mathematically correct result can describe the wrong circuit or boundary condition if the model was set up incorrectly.','concepts'=>['b633-ree-math-calculus-differential']],
            ['id'=>'complex-numbers-phasors-and-transforms','heading'=>'3. Complex numbers, phasors, Fourier, and Laplace methods','body'=>'Complex numbers combine real and imaginary components; magnitude and angle offer a useful representation for sinusoidal steady-state quantities. A phasor is tied to a common frequency and convention, and it does not describe arbitrary transient behavior by itself. Fourier methods represent periodic content through frequency components, while Laplace transforms can solve linear differential systems with specified initial conditions. Keep transform variables, units, and initial-value terms visible. Check whether the problem asks for steady state, transient response, or a periodic decomposition before selecting a method.','concepts'=>['b633-ree-math-complex-phasors','b633-ree-math-fourier-laplace','b633-ree-math-sequences-series']],
            ['id'=>'probability-trigonometry-and-engineering-economics','heading'=>'4. Probability, geometry, and economic comparisons','body'=>'Probability and statistics quantify uncertainty using a defined sample space, data collection process, and model. Check assumptions before applying a distribution or interpreting a confidence measure. Trigonometry and analytic geometry connect angles, lengths, and coordinates; label the reference angle and units. Engineering-economics calculations compare alternatives using timing, interest, service horizon, and stated costs. A present-worth result is conditional on the inputs and does not make a safety or ethical tradeoff automatically acceptable.','concepts'=>['b633-ree-math-probability-statistics','b633-ree-math-discrete-economics','b633-ree-math-trigonometry-analytic-geometry']],
        ],
        'examples'=>[['heading'=>'Solve a two-equation current model','prompt'=>'A feeder model gives 2x + y = 11 and x − y = 1, where x and y are branch currents in amperes. Find x.','steps'=>['Add the equations to eliminate y: 3x = 12.','Divide by 3 to get x = 4 A.','Substitute into x − y = 1 to obtain y = 3 A, then verify 2(4) + 3 = 11.'],'answer'=>'x = 4 A.','check'=>'Both unknowns satisfy both original equations.']],
        'misconceptions'=>['A solved equation system is correct without substitution.','A phasor represents every time-varying waveform.','More displayed digits mean greater measurement accuracy.'],
        'patterns'=>['Check every original constraint after solving.','Match the mathematical method to the time behavior.','Name model, units, and assumptions for data or economic analysis.'],
        'questions'=>[['id'=>'1569','section'=>'linear-systems-and-matrices','concept'=>'b633-ree-math-algebra-linear','sources'=>['prc-ree-enhanced-tos-annex-a-2024','openstax-precalculus-2e']]],
    ],
];

$activeScopes = [];
foreach (\App\Services\Board\BoardViewService::all() as $board) {
    if (!is_array($board)) continue;
    $boardId = strtolower((string) ($board['id'] ?? ''));
    foreach ((array) ($board['practice_subjects'] ?? []) as $subject) {
        if (!is_array($subject) || (int) ($subject['available_questions'] ?? 0) < 1) continue;
        $subjectId = strtolower((string) ($subject['id'] ?? ''));
        if ($boardId !== '' && $subjectId !== '') $activeScopes[$boardId . '|' . $subjectId] = true;
    }
}
$materials = $storage->all('study-materials');
$lessons = $storage->all('study-lessons');
$links = $storage->all('study-question-links');
$questions = $storage->all('questions');
$questionById = [];
foreach ($questions as $question) {
    if (is_array($question)) $questionById[(string) ($question['id'] ?? '')] = $question;
}
$eligibility = \App\Services\Question\QuestionEligibilityService::index();
$materialIds = [];
$lessonIds = [];
$linkPairs = [];
foreach ($materials as $material) if (is_array($material)) $materialIds[(string) ($material['id'] ?? '')] = true;
foreach ($lessons as $lesson) if (is_array($lesson)) $lessonIds[(string) ($lesson['id'] ?? '')] = true;
foreach ($links as $link) if (is_array($link)) $linkPairs[(string) ($link['material_id'] ?? '') . "\0" . (string) ($link['question_id'] ?? '')] = true;

$createdLessons = 0;
$createdMaterials = 0;
$createdLinks = 0;
$skippedLessons = 0;
foreach ($specs as $spec) {
    $lessonId = (string) $spec['id'];
    $materialId = $lessonId;
    $subjectId = (string) $spec['subject'];
    $boardId = (string) $spec['board'];
    if (!isset($activeScopes[strtolower($boardId . '|' . $subjectId)])) throw new RuntimeException("Inactive board/subject selector {$boardId}/{$subjectId} for {$lessonId}.");
    foreach (array_merge($spec['scope'], $spec['instruction']) as $sourceId) {
        if (!isset($sourceIds[(string) $sourceId])) throw new RuntimeException("Unregistered source {$sourceId} for {$lessonId}.");
    }
    foreach ($spec['sections'] as $section) {
        if (!is_array($section) || trim((string) ($section['id'] ?? '')) === '' || trim((string) ($section['body'] ?? '')) === '') {
            throw new RuntimeException("Invalid section in {$lessonId}.");
        }
        foreach ((array) ($section['concepts'] ?? []) as $conceptId) {
            if (!isset($concepts[(string) $conceptId])) throw new RuntimeException("Unknown concept {$conceptId} in {$lessonId}/{$section['id']}.");
        }
    }
    if (isset($lessonIds[$lessonId]) || isset($materialIds[$materialId])) {
        if (isset($lessonIds[$lessonId]) && isset($materialIds[$materialId])) {
            $skippedLessons++;
            continue;
        }
        throw new RuntimeException("Conflicting partial record already exists for {$lessonId}; refusing to replace it.");
    }

    $allConcepts = [];
    $allTopics = [];
    $sectionRows = [];
    foreach ($spec['sections'] as $section) {
        $relatedConceptIds = array_values(array_unique(array_map('strval', (array) ($section['concepts'] ?? []))));
        $relatedTopicIds = [];
        foreach ($relatedConceptIds as $conceptId) {
            $allConcepts[$conceptId] = true;
            $topicId = (string) ($concepts[$conceptId]['topic_id'] ?? '');
            if ($topicId !== '') {
                $relatedTopicIds[$topicId] = true;
                $allTopics[$topicId] = true;
            }
        }
        $sectionRows[] = [
            'id' => (string) $section['id'],
            'heading' => (string) $section['heading'],
            'body' => (string) $section['body'],
            'items' => array_values(array_map('strval', (array) ($section['items'] ?? []))),
            'related_concept_ids' => $relatedConceptIds,
            'related_topic_ids' => array_keys($relatedTopicIds),
        ];
    }
    $allConceptIds = array_keys($allConcepts);
    $allTopicIds = array_keys($allTopics);
    $firstConcept = $allConceptIds[0] ?? '';
    $firstTopic = $firstConcept !== '' ? (string) ($concepts[$firstConcept]['topic_id'] ?? '') : '';
    $notes = [];
    foreach ($spec['sections'] as $section) $notes[] = [(string) $section['heading'], (string) $section['body']];
    $materials[] = [
        'id' => $materialId,
        'title' => (string) $spec['title'],
        'summary' => 'Original instructional lesson with selected worked examples; the scope note identifies competencies not covered by this short module.',
        'notes' => $notes,
        'source_ids' => array_values(array_unique(array_merge($spec['scope'], $spec['instruction']))),
        'exams' => [$boardId],
        'taxonomy' => ['subject_id' => $subjectId, 'topic_id' => $firstTopic, 'concept_id' => $firstConcept, 'topic_ids' => $allTopicIds, 'concept_ids' => $allConceptIds],
        'status' => 'published',
        'version' => 1,
        'updated_at' => '2026-10-19',
    ];
    $materialIds[$materialId] = true;

    $practiceIds = [];
    foreach ((array) ($spec['questions'] ?? []) as $questionSpec) {
        $questionId = (string) ($questionSpec['id'] ?? '');
        $sectionId = (string) ($questionSpec['section'] ?? '');
        $conceptId = (string) ($questionSpec['concept'] ?? '');
        if (!isset($questionById[$questionId])) throw new RuntimeException("Missing canonical question {$questionId} for {$lessonId}.");
        $question = $questionById[$questionId];
        if ((string) ($question['taxonomy']['concept_id'] ?? '') !== $conceptId) throw new RuntimeException("Question {$questionId} taxonomy does not match the inspected lesson mapping concept {$conceptId}.");
        $placement = \App\Services\Question\QuestionEligibilityService::forExam($question, $boardId, $eligibility);
        if (!is_array($placement) || (string) ($placement['subject_id'] ?? '') !== $subjectId) throw new RuntimeException("Question {$questionId} is not eligible in {$boardId}/{$subjectId}.");
        $section = null;
        foreach ($sectionRows as $row) if ($row['id'] === $sectionId) $section = $row;
        if (!is_array($section) || !in_array($conceptId, $section['related_concept_ids'], true)) throw new RuntimeException("Question {$questionId} has no exact concept section in {$lessonId}.");
        $questionSourceIds = array_values(array_unique(array_map('strval', (array) ($questionSpec['sources'] ?? []))));
        foreach ($questionSourceIds as $sourceId) {
            if (!isset($sourceIds[$sourceId]) || !in_array($sourceId, array_merge($spec['scope'], $spec['instruction']), true)) throw new RuntimeException("Invalid link source {$sourceId} for question {$questionId}.");
        }
        $practiceIds[] = $questionId;
        $pair = $materialId . "\0" . $questionId;
        if (!isset($linkPairs[$pair])) {
            $links[] = [
                'id' => 'batch696-' . $lessonId . '-' . $questionId,
                'material_id' => $materialId,
                'question_id' => $questionId,
                'source_ids' => $questionSourceIds,
                'section_id' => $sectionId,
                'review_guidance' => 'Review the exact lesson section: ' . (string) $section['heading'],
                'semantic_review_status' => 'SECTION_AND_SOURCE_CHECKED_PENDING_INDEPENDENT_ACADEMIC_REVIEW',
            ];
            $linkPairs[$pair] = true;
            $createdLinks++;
        }
    }

    $lessons[] = [
        'id' => $lessonId,
        'title' => (string) $spec['title'],
        'material_id' => $materialId,
        'status' => 'published',
        'version' => 1,
        'board_id' => $boardId,
        'subject_id' => $subjectId,
        'official_scope_source_ids' => array_values(array_unique(array_map('strval', $spec['scope']))),
        'instructional_source_ids' => array_values(array_unique(array_map('strval', $spec['instruction']))),
        'scope_note' => (string) $spec['scope_note'],
        'learning_objectives' => array_values(array_map('strval', (array) ($spec['objectives'] ?? []))),
        'sections' => $sectionRows,
        'worked_examples' => array_values((array) ($spec['examples'] ?? [])),
        'common_misconceptions' => array_values(array_map('strval', (array) ($spec['misconceptions'] ?? []))),
        'question_patterns' => array_values(array_map('strval', (array) ($spec['patterns'] ?? []))),
        'practice_question_ids' => array_values(array_unique($practiceIds)),
        'pdf_file' => (string) $spec['pdf'],
        'source_review' => [
            'status' => 'SOURCE_CHECKED',
            'checked_at' => '2026-10-19',
            'note' => 'Scope and the cited instructional claims were checked against the registered official or academic sources documented in the Batch 696 source-evidence report. Source checking is not independent academic review or human learner-effectiveness evidence.',
        ],
    ];
    $lessonIds[$lessonId] = true;
    $createdLessons++;
    $createdMaterials++;
}

$storage->replace('study-materials', $materials);
$storage->replace('study-lessons', $lessons);
$storage->replace('study-question-links', $links);
printf("STATUS=PASS LESSONS_CREATED=%d MATERIALS_CREATED=%d QUESTION_LINKS_CREATED=%d LESSONS_SKIPPED_IDEMPOTENT=%d\n", $createdLessons, $createdMaterials, $createdLinks, $skippedLessons);
